    } else if (data->tnl_type == OVS_VPORT_TYPE_ERSPAN ||
               data->tnl_type == OVS_VPORT_TYPE_IP6ERSPAN) {
        const struct gre_base_hdr *greh;
        const struct erspan_base_hdr *ersh;

        greh = (const struct gre_base_hdr *) l4;
